from collections import defaultdict, deque

def check_girth(edges, n, min_girth):
    """Check if graph has girth >= min_girth using BFS"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
