def check_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = {colors[u] for u in adj[v] if colors[u] != -1}
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

